CREATE INDEX IF NOT EXISTS india_spatial_boundaries_geom_gix ON public.india_spatial_boundaries USING gist(geom);

-- 2. HELPER FUNCTIONS USING SPATIAL BOUNDARY TABLE AND POSTGIS ST_COVERS
CREATE OR REPLACE FUNCTION public.is_coord_in_india(p_lat numeric, p_lon numeric)
RETURNS boolean
LANGUAGE plpgsql
STABLE
AS $$
BEGIN
  IF p_lat IS NULL OR p_lon IS NULL OR p_lat < -90 OR p_lat > 90 OR p_lon < -180 OR p_lon > 180 THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1 FROM public.india_spatial_boundaries
    WHERE ST_Covers(geom, ST_SetSRID(ST_MakePoint(p_lon, p_lat), 4326))
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.is_coord_in_india(p_lat double precision, p_lon double precision)
RETURNS boolean
LANGUAGE sql
STABLE
AS $$
  SELECT public.is_coord_in_india(p_lat::numeric, p_lon::numeric);
$$;

CREATE OR REPLACE FUNCTION public.is_route_in_india(p_route_polyline geography)
RETURNS boolean
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  v_geom geometry;
  v_num_pts integer;
  i integer;
  s integer;
  pt1 geometry;
  pt2 geometry;
  seg geometry;
  dist double precision;
  sample_pt geometry;
  steps integer;
BEGIN
  IF p_route_polyline IS NULL THEN
    RETURN false;
  END IF;

  v_geom := p_route_polyline::geometry;
  v_num_pts := ST_NPoints(v_geom);
  IF v_num_pts IS NULL OR v_num_pts < 2 THEN
    RETURN false;
  END IF;

  -- 1. Check all vertex points
  FOR i IN 1..v_num_pts LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.india_spatial_boundaries
      WHERE ST_Covers(geom, ST_PointN(v_geom, i))
    ) THEN
      RETURN false;
    END IF;
  END LOOP;

  -- 2. Check line segments between consecutive vertices
  FOR i IN 1..(v_num_pts - 1) LOOP
    pt1 := ST_PointN(v_geom, i);
    pt2 := ST_PointN(v_geom, i + 1);
    dist := ST_Distance(pt1::geography, pt2::geography);

    IF dist > 1000 THEN -- Only sample segments longer than 1km
      seg := ST_MakeLine(pt1, pt2);
      steps := LEAST(15, GREATEST(5, (dist / 5000)::integer));
      FOR s IN 1..(steps - 1) LOOP
        sample_pt := ST_LineInterpolatePoint(seg, (s::double precision / steps::double precision));
        IF NOT EXISTS (
          SELECT 1 FROM public.india_spatial_boundaries
          WHERE ST_Covers(geom, sample_pt)
        ) THEN
          -- Reject if non-boundary sample point occurs on a segment longer than 15km
          IF dist > 15000 THEN
            RETURN false;
          END IF;
        END IF;
      END LOOP;
    END IF;
  END LOOP;

  RETURN true;
END;
$$;

GRANT EXECUTE ON FUNCTION public.is_coord_in_india(numeric, numeric) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_coord_in_india(double precision, double precision) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_route_in_india(geography) TO authenticated, service_role;
GRANT SELECT ON TABLE public.india_spatial_boundaries TO authenticated, service_role, anon;


-- 3. TRIGGER FUNCTION FOR TRIP_ROUTES TABLE
CREATE OR REPLACE FUNCTION public.trg_fn_enforce_india_trip_routes()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_orig_lat numeric;
  v_orig_lon numeric;
  v_dest_lat numeric;
  v_dest_lon numeric;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_orig_lat := ST_Y(NEW.origin_geo::geometry);
    v_orig_lon := ST_X(NEW.origin_geo::geometry);
    v_dest_lat := ST_Y(NEW.dest_geo::geometry);
    v_dest_lon := ST_X(NEW.dest_geo::geometry);

    IF NOT public.is_coord_in_india(v_orig_lat, v_orig_lon) THEN
      RAISE EXCEPTION 'Trip origin location (%) must be inside India coverage.', NEW.origin_name;
    END IF;

    IF NOT public.is_coord_in_india(v_dest_lat, v_dest_lon) THEN
      RAISE EXCEPTION 'Trip destination location (%) must be inside India coverage.', NEW.dest_name;
    END IF;

    IF NEW.route_polyline IS NOT NULL THEN
      IF NOT public.is_route_in_india(NEW.route_polyline) THEN
        RAISE EXCEPTION 'Trip route crosses outside India service coverage.';
      END IF;
    END IF;

    IF NEW.currency IS NOT NULL AND UPPER(TRIM(NEW.currency)) <> 'INR' THEN
      RAISE EXCEPTION 'Only INR currency is supported for new transactions.';
    END IF;
    NEW.currency := 'INR';
    NEW.jurisdiction_code := 'IN';
  ELSIF TG_OP = 'UPDATE' THEN
    IF (NEW.origin_geo IS DISTINCT FROM OLD.origin_geo) THEN
      v_orig_lat := ST_Y(NEW.origin_geo::geometry);
      v_orig_lon := ST_X(NEW.origin_geo::geometry);
      IF NOT public.is_coord_in_india(v_orig_lat, v_orig_lon) THEN
        RAISE EXCEPTION 'Trip origin location (%) must be inside India coverage.', NEW.origin_name;
      END IF;
    END IF;

    IF (NEW.dest_geo IS DISTINCT FROM OLD.dest_geo) THEN
      v_dest_lat := ST_Y(NEW.dest_geo::geometry);
      v_dest_lon := ST_X(NEW.dest_geo::geometry);
      IF NOT public.is_coord_in_india(v_dest_lat, v_dest_lon) THEN
        RAISE EXCEPTION 'Trip destination location (%) must be inside India coverage.', NEW.dest_name;
      END IF;
    END IF;

    IF (NEW.route_polyline IS DISTINCT FROM OLD.route_polyline) AND NEW.route_polyline IS NOT NULL THEN
      IF NOT public.is_route_in_india(NEW.route_polyline) THEN
        RAISE EXCEPTION 'Trip route crosses outside India service coverage.';
      END IF;
    END IF;

    IF NEW.currency IS DISTINCT FROM OLD.currency AND UPPER(TRIM(NEW.currency)) <> 'INR' THEN
      RAISE EXCEPTION 'Only INR currency is supported for new transactions.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_enforce_india_trip_routes ON public.trip_routes;
CREATE TRIGGER trg_enforce_india_trip_routes
  BEFORE INSERT OR UPDATE ON public.trip_routes
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_fn_enforce_india_trip_routes();


-- 4. TRIGGER FUNCTION FOR RIDE_REQUESTS TABLE
CREATE OR REPLACE FUNCTION public.trg_fn_enforce_india_ride_requests()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_pickup_lat numeric;
  v_pickup_lon numeric;
  v_drop_lat numeric;
  v_drop_lon numeric;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.pickup_geo IS NOT NULL THEN
      v_pickup_lat := ST_Y(NEW.pickup_geo::geometry);
      v_pickup_lon := ST_X(NEW.pickup_geo::geometry);
      IF NOT public.is_coord_in_india(v_pickup_lat, v_pickup_lon) THEN
        RAISE EXCEPTION 'Ride request pickup location (%) must be inside India coverage.', NEW.pickup_name;
      END IF;
    END IF;

    IF NEW.drop_geo IS NOT NULL THEN
      v_drop_lat := ST_Y(NEW.drop_geo::geometry);
      v_drop_lon := ST_X(NEW.drop_geo::geometry);
      IF NOT public.is_coord_in_india(v_drop_lat, v_drop_lon) THEN
        RAISE EXCEPTION 'Ride request drop location (%) must be inside India coverage.', NEW.drop_name;
      END IF;
    END IF;

    IF NEW.currency IS NOT NULL AND UPPER(TRIM(NEW.currency)) <> 'INR' THEN
      RAISE EXCEPTION 'Only INR currency is supported for new transactions.';
    END IF;
    NEW.currency := 'INR';
    NEW.jurisdiction_code := 'IN';
  ELSIF TG_OP = 'UPDATE' THEN
    IF (NEW.pickup_geo IS DISTINCT FROM OLD.pickup_geo) THEN
      IF NEW.pickup_geo IS NOT NULL THEN
        v_pickup_lat := ST_Y(NEW.pickup_geo::geometry);
        v_pickup_lon := ST_X(NEW.pickup_geo::geometry);
        IF NOT public.is_coord_in_india(v_pickup_lat, v_pickup_lon) THEN
          RAISE EXCEPTION 'Ride request pickup location (%) must be inside India coverage.', NEW.pickup_name;
        END IF;
      END IF;
    END IF;

    IF (NEW.drop_geo IS DISTINCT FROM OLD.drop_geo) THEN
      IF NEW.drop_geo IS NOT NULL THEN
        v_drop_lat := ST_Y(NEW.drop_geo::geometry);
        v_drop_lon := ST_X(NEW.drop_geo::geometry);
        IF NOT public.is_coord_in_india(v_drop_lat, v_drop_lon) THEN
          RAISE EXCEPTION 'Ride request drop location (%) must be inside India coverage.', NEW.drop_name;
        END IF;
      END IF;
    END IF;

    IF NEW.currency IS DISTINCT FROM OLD.currency AND UPPER(TRIM(NEW.currency)) <> 'INR' THEN
      RAISE EXCEPTION 'Only INR currency is supported for new transactions.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_enforce_india_ride_requests ON public.ride_requests;
CREATE TRIGGER trg_enforce_india_ride_requests
  BEFORE INSERT OR UPDATE ON public.ride_requests
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_fn_enforce_india_ride_requests();


-- 5. TRIGGER FUNCTION FOR MARKETPLACE_ITEMS TABLE
CREATE OR REPLACE FUNCTION public.trg_fn_enforce_india_marketplace_items()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_item_lat numeric;
  v_item_lon numeric;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.location_geo IS NOT NULL THEN
      v_item_lat := ST_Y(NEW.location_geo::geometry);
      v_item_lon := ST_X(NEW.location_geo::geometry);

      IF NOT public.is_coord_in_india(v_item_lat, v_item_lon) THEN
        RAISE EXCEPTION 'Marketplace listing location (%) must be inside India coverage.', NEW.location_name;
      END IF;
    END IF;

    IF NEW.currency IS NOT NULL AND UPPER(TRIM(NEW.currency)) <> 'INR' THEN
      RAISE EXCEPTION 'Only INR currency is supported for new transactions.';
    END IF;
    NEW.currency := 'INR';
    NEW.jurisdiction_code := 'IN';
  ELSIF TG_OP = 'UPDATE' THEN
    IF (NEW.location_geo IS DISTINCT FROM OLD.location_geo) THEN
      IF NEW.location_geo IS NOT NULL THEN
        v_item_lat := ST_Y(NEW.location_geo::geometry);
        v_item_lon := ST_X(NEW.location_geo::geometry);

        IF NOT public.is_coord_in_india(v_item_lat, v_item_lon) THEN
          RAISE EXCEPTION 'Marketplace listing location (%) must be inside India coverage.', NEW.location_name;
        END IF;
      END IF;
    END IF;

    IF NEW.currency IS DISTINCT FROM OLD.currency AND UPPER(TRIM(NEW.currency)) <> 'INR' THEN
      RAISE EXCEPTION 'Only INR currency is supported for new transactions.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_enforce_india_marketplace_items ON public.marketplace_items;
CREATE TRIGGER trg_enforce_india_marketplace_items
  BEFORE INSERT OR UPDATE ON public.marketplace_items
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_fn_enforce_india_marketplace_items();


-- 6. TRIGGER FUNCTION FOR SHIPMENT_TASKS TABLE
CREATE OR REPLACE FUNCTION public.trg_fn_enforce_india_shipment_tasks()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_pickup_lat numeric;
  v_pickup_lon numeric;
  v_drop_lat numeric;
  v_drop_lon numeric;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.pickup_geo IS NOT NULL THEN
      v_pickup_lat := ST_Y(NEW.pickup_geo::geometry);
      v_pickup_lon := ST_X(NEW.pickup_geo::geometry);
      IF NOT public.is_coord_in_india(v_pickup_lat, v_pickup_lon) THEN
        RAISE EXCEPTION 'Parcel pickup location must be inside India coverage.';
      END IF;
    END IF;

    IF NEW.drop_geo IS NOT NULL THEN
      v_drop_lat := ST_Y(NEW.drop_geo::geometry);
      v_drop_lon := ST_X(NEW.drop_geo::geometry);
      IF NOT public.is_coord_in_india(v_drop_lat, v_drop_lon) THEN
        RAISE EXCEPTION 'Parcel drop location must be inside India coverage.';
      END IF;
    END IF;

    IF NEW.currency IS NOT NULL AND UPPER(TRIM(NEW.currency)) <> 'INR' THEN
      RAISE EXCEPTION 'Only INR currency is supported for new transactions.';
    END IF;
    NEW.currency := 'INR';
  ELSIF TG_OP = 'UPDATE' THEN
    IF (NEW.pickup_geo IS DISTINCT FROM OLD.pickup_geo) THEN
      IF NEW.pickup_geo IS NOT NULL THEN
        v_pickup_lat := ST_Y(NEW.pickup_geo::geometry);
        v_pickup_lon := ST_X(NEW.pickup_geo::geometry);
        IF NOT public.is_coord_in_india(v_pickup_lat, v_pickup_lon) THEN
          RAISE EXCEPTION 'Parcel pickup location must be inside India coverage.';
        END IF;
      END IF;
    END IF;

    IF (NEW.drop_geo IS DISTINCT FROM OLD.drop_geo) THEN
      IF NEW.drop_geo IS NOT NULL THEN
        v_drop_lat := ST_Y(NEW.drop_geo::geometry);
        v_drop_lon := ST_X(NEW.drop_geo::geometry);
        IF NOT public.is_coord_in_india(v_drop_lat, v_drop_lon) THEN
          RAISE EXCEPTION 'Parcel drop location must be inside India coverage.';
        END IF;
      END IF;
    END IF;

    IF NEW.currency IS DISTINCT FROM OLD.currency AND UPPER(TRIM(NEW.currency)) <> 'INR' THEN
      RAISE EXCEPTION 'Only INR currency is supported for new transactions.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_enforce_india_shipment_tasks ON public.shipment_tasks;
CREATE TRIGGER trg_enforce_india_shipment_tasks
  BEFORE INSERT OR UPDATE ON public.shipment_tasks
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_fn_enforce_india_shipment_tasks();


-- 7. RESTORE ESTABLISHED RESERVE_MARKETPLACE_PURCHASE RPC WITH SURGICAL GEOGRAPHIC CHECKS
CREATE OR REPLACE FUNCTION public.reserve_marketplace_purchase(
  p_actor_id uuid,
  p_item_id uuid,
  p_quantity integer,
  p_fulfillment_mode text,
  p_delivery_reward numeric,
  p_idempotency_key text,
  p_dest_name text DEFAULT NULL,
  p_dest_lat numeric DEFAULT NULL,
  p_dest_lng numeric DEFAULT NULL,
  p_weight_kg numeric DEFAULT 1.0
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  existing_purchase public.marketplace_purchases;
  existing_order public.escrow_orders;
  i public.marketplace_items;
  v_policy public.cost_sharing_policies;
  v_subtotal numeric(12,2);
  v_reward numeric(12,2);
  v_bps integer;
  v_fee numeric(12,2);
  v_total numeric(12,2);
  v_purchase public.marketplace_purchases;
  v_order public.escrow_orders;
  v_task public.shipment_tasks;
  v_dest_geo geography(Point,4326);
  v_thread_id uuid;
  v_existing_task_id uuid;
  v_item_lat numeric;
  v_item_lon numeric;
BEGIN
  -- Strict authentication check
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_actor_id <> auth.uid() THEN
    RAISE EXCEPTION 'Cannot impersonate another user';
  END IF;

  -- Input validation
  IF p_quantity < 1 THEN
    RAISE EXCEPTION 'Purchase quantity must be at least 1';
  END IF;

  IF p_fulfillment_mode NOT IN ('LOCAL_HANDOFF', 'PARCELPOOL') THEN
    RAISE EXCEPTION 'Invalid fulfillment mode';
  END IF;

  IF p_fulfillment_mode = 'LOCAL_HANDOFF' THEN
    IF COALESCE(p_delivery_reward, 0) <> 0 THEN
      RAISE EXCEPTION 'Local handoff delivery reward must be zero';
    END IF;
    v_reward := 0;
  ELSE
    IF p_delivery_reward IS NULL OR p_delivery_reward < 0 THEN
      RAISE EXCEPTION 'Invalid delivery reward for ParcelPool crowdshipping';
    END IF;
    v_reward := p_delivery_reward;

    IF p_dest_name IS NULL OR char_length(trim(p_dest_name)) < 2 THEN
      RAISE EXCEPTION 'ParcelPool crowdshipping requires a valid destination address name';
    END IF;

    IF p_dest_lat IS NULL OR p_dest_lng IS NULL OR p_dest_lat < -90 OR p_dest_lat > 90 OR p_dest_lng < -180 OR p_dest_lng > 180 THEN
      RAISE EXCEPTION 'ParcelPool crowdshipping requires valid destination coordinates';
    END IF;

    -- Surgical Geographic Verification for ParcelPool destination
    IF NOT public.is_coord_in_india(p_dest_lat, p_dest_lng) THEN
      RAISE EXCEPTION 'ParcelPool destination location must be inside India service coverage';
    END IF;

    v_dest_geo := ST_SetSRID(ST_MakePoint(p_dest_lng, p_dest_lat), 4326)::geography;
  END IF;

  -- Idempotency security check
  SELECT * INTO existing_purchase FROM public.marketplace_purchases WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF existing_purchase.buyer_id <> p_actor_id OR existing_purchase.item_id <> p_item_id OR existing_purchase.quantity <> p_quantity OR existing_purchase.fulfillment_mode <> p_fulfillment_mode THEN
      RAISE EXCEPTION 'Idempotency key reuse with mismatched parameters or unauthorized actor';
    END IF;

    SELECT * INTO existing_order FROM public.escrow_orders WHERE id = existing_purchase.escrow_order_id;
    SELECT id INTO v_existing_task_id FROM public.shipment_tasks WHERE marketplace_purchase_id = existing_purchase.id LIMIT 1;

    SELECT id INTO v_thread_id FROM public.chat_threads WHERE order_id = existing_order.id LIMIT 1;

    RETURN jsonb_build_object(
      'purchase', to_jsonb(existing_purchase),
      'escrow_order', to_jsonb(existing_order),
      'shipment_task_id', v_existing_task_id,
      'chat_thread_id', v_thread_id
    );
  END IF;

  -- Lock item row for atomic inventory check
  SELECT * INTO i FROM public.marketplace_items WHERE id = p_item_id FOR UPDATE;
  IF NOT FOUND OR i.status <> 'LISTED' OR i.available_quantity < p_quantity THEN
    RAISE EXCEPTION 'Insufficient item stock available';
  END IF;

  IF i.seller_id = p_actor_id THEN
    RAISE EXCEPTION 'Seller cannot purchase own item';
  END IF;

  IF p_fulfillment_mode = 'PARCELPOOL' AND NOT i.ship_eligible THEN
    RAISE EXCEPTION 'This item is not eligible for ParcelPool crowdshipping';
  END IF;

  -- Surgical Geographic Verification for stored listing item coordinates
  IF i.location_geo IS NOT NULL THEN
    v_item_lat := ST_Y(i.location_geo::geometry);
    v_item_lon := ST_X(i.location_geo::geometry);
    IF NOT public.is_coord_in_india(v_item_lat, v_item_lon) THEN
      RAISE EXCEPTION 'Marketplace listing location is outside India service coverage';
    END IF;
  END IF;

  -- Canonical Jurisdiction / Cost-Sharing Policy Lookup & Platform Fee BPS Derivation
  SELECT * INTO v_policy FROM public.cost_sharing_policies
  WHERE jurisdiction_code = i.jurisdiction_code AND enabled IS TRUE;
  IF NOT FOUND OR v_policy.marketplace_platform_fee_bps IS NULL THEN
    RAISE EXCEPTION 'No enabled marketplace platform fee policy for jurisdiction %', i.jurisdiction_code;
  END IF;

  IF i.currency <> v_policy.currency THEN
    RAISE EXCEPTION 'Item currency % does not match jurisdiction policy currency %', i.currency, v_policy.currency;
  END IF;

  v_bps := v_policy.marketplace_platform_fee_bps;

  -- Authoritative DB price & fee calculation
  v_subtotal := i.price * p_quantity;
  v_fee := round(v_subtotal * v_bps / 10000.0, 2);
  v_total := v_subtotal + v_reward + v_fee;

  -- Enable session variable for inventory mutation
  PERFORM set_config('shipdehop.allow_inventory_mutation', 'true', true);

  -- Atomic inventory decrement
  UPDATE public.marketplace_items
  SET available_quantity = available_quantity - p_quantity,
      status = (CASE WHEN (available_quantity - p_quantity) = 0 THEN 'SOLD'::public.marketplace_item_status ELSE status END),
      updated_at = now()
  WHERE id = i.id;

  -- Insert Escrow Order (HopPay Escrow Engine)
  INSERT INTO public.escrow_orders (
    order_type, buyer_id, provider_id, marketplace_item_id, total_amount, base_price, reward_fee, platform_fee,
    currency, escrow_status, fulfillment_status, reservation_expires_at
  ) VALUES (
    'MARKETPLACE', p_actor_id, i.seller_id, i.id, v_total, v_subtotal, v_reward, v_fee,
    i.currency, 'PENDING', 'CREATED', now() + INTERVAL '15 minutes'
  ) RETURNING * INTO v_order;

  -- Insert Marketplace Purchase (Commerce Entity)
  INSERT INTO public.marketplace_purchases (
    item_id, buyer_id, seller_id, quantity, unit_price, subtotal, fulfillment_mode, delivery_reward, platform_fee,
    total_amount, currency, jurisdiction_code, status, escrow_order_id, idempotency_key
  ) VALUES (
    i.id, p_actor_id, i.seller_id, p_quantity, i.price, v_subtotal, p_fulfillment_mode, v_reward, v_fee,
    v_total, i.currency, i.jurisdiction_code, 'PENDING', v_order.id, p_idempotency_key
  ) RETURNING * INTO v_purchase;

  -- Create Seller Proceeds Payout Allocation
  INSERT INTO public.escrow_payout_allocations (
    order_id, recipient_id, allocation_type, amount, currency, status, idempotency_key
  ) VALUES (
    v_order.id, i.seller_id, 'SELLER_PROCEEDS', v_subtotal, i.currency, 'PENDING',
    'seller_proceeds:' || v_order.id || ':' || i.seller_id
  );

  -- If PARCELPOOL crowdshipping selected, create linked shipment task with buyer_id as sender_id (requester/payer)
  IF p_fulfillment_mode = 'PARCELPOOL' THEN
    INSERT INTO public.shipment_tasks (
      sender_id, item_type, declared_value, reward_amount, currency, weight_kg, status, inspection_status,
      pickup_name, drop_name, pickup_geo, drop_geo, marketplace_purchase_id
    ) VALUES (
      p_actor_id, 'PARCEL'::public.shipment_item_type, v_subtotal, v_reward, i.currency, COALESCE(p_weight_kg, 1.0),
      'OPEN'::public.shipment_status, 'PENDING'::public.shipment_inspection_status,
      i.location_name, trim(p_dest_name), i.location_geo, v_dest_geo, v_purchase.id
    ) RETURNING * INTO v_task;
  END IF;

  -- Fetch canonical chat thread automatically created for THIS escrow order ID by trigger
  SELECT id INTO v_thread_id FROM public.chat_threads WHERE order_id = v_order.id LIMIT 1;

  -- Dispatch idempotent notification to Seller
  -- Dispatch idempotent notification to Seller
  PERFORM public.create_notification(
    i.seller_id,
    'PARCEL_RESERVED',
    'Item purchased',
    'A buyer has purchased ' || p_quantity || ' unit(s) of ' || i.title,
    'ORDER',
    v_order.id,
    'marketplace_purchased:' || v_purchase.id || ':' || i.seller_id,
    v_order.id,
    NULL,
    NULL
  );

  RETURN jsonb_build_object(
    'purchase', to_jsonb(v_purchase),
    'escrow_order', to_jsonb(v_order),
    'shipment_task_id', CASE WHEN v_task.id IS NOT NULL THEN v_task.id ELSE NULL END,
    'chat_thread_id', v_thread_id
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.reserve_marketplace_purchase(uuid, uuid, integer, text, numeric, text, text, numeric, numeric, numeric) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.reserve_marketplace_purchase(uuid, uuid, integer, text, numeric, text, text, numeric, numeric, numeric) TO authenticated, service_role;


-- 8. RESTORE ESTABLISHED RESERVE_RIDE_ORDER RPC WITH SURGICAL GEOGRAPHIC CHECKS
CREATE OR REPLACE FUNCTION public.reserve_ride_order(
  p_actor_id uuid,
  p_trip_id uuid,
  p_quantity integer,
  p_platform_fee_bps integer
)
RETURNS public.escrow_orders
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  t public.trip_routes;
  v_actor_id uuid;
  v_base numeric(12,2);
  v_fee numeric(12,2);
  v_order public.escrow_orders;
  v_orig_lat numeric;
  v_orig_lon numeric;
  v_dest_lat numeric;
  v_dest_lon numeric;
BEGIN
  IF auth.role() = 'authenticated' THEN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
    IF p_actor_id IS NOT NULL AND p_actor_id <> auth.uid() THEN
      RAISE EXCEPTION 'Cannot impersonate another user';
    END IF;
    v_actor_id := auth.uid();
  ELSE
    v_actor_id := p_actor_id;
  END IF;

  IF v_actor_id IS NULL OR p_quantity < 1 OR p_quantity > 8 THEN RAISE EXCEPTION 'Invalid reservation'; END IF;
  IF p_platform_fee_bps < 0 OR p_platform_fee_bps > 3000 THEN RAISE EXCEPTION 'Invalid platform fee'; END IF;

  SELECT * INTO t FROM public.trip_routes WHERE id = p_trip_id FOR UPDATE;
  IF NOT FOUND OR t.status <> 'SCHEDULED' OR t.departure_time <= now() THEN RAISE EXCEPTION 'Trip unavailable'; END IF;

  -- Surgical Geographic Verification for stored trip coordinates
  IF t.origin_geo IS NOT NULL THEN
    v_orig_lat := ST_Y(t.origin_geo::geometry);
    v_orig_lon := ST_X(t.origin_geo::geometry);
    IF NOT public.is_coord_in_india(v_orig_lat, v_orig_lon) THEN
      RAISE EXCEPTION 'Trip origin location is outside India service coverage';
    END IF;
  END IF;

  IF t.dest_geo IS NOT NULL THEN
    v_dest_lat := ST_Y(t.dest_geo::geometry);
    v_dest_lon := ST_X(t.dest_geo::geometry);
    IF NOT public.is_coord_in_india(v_dest_lat, v_dest_lon) THEN
      RAISE EXCEPTION 'Trip destination location is outside India service coverage';
    END IF;
  END IF;

  IF t.route_polyline IS NOT NULL THEN
    IF NOT public.is_route_in_india(t.route_polyline) THEN
      RAISE EXCEPTION 'Trip route crosses outside India service coverage';
    END IF;
  END IF;

  IF t.driver_id = v_actor_id THEN RAISE EXCEPTION 'Driver cannot book own trip'; END IF;
  IF t.available_seats < p_quantity THEN RAISE EXCEPTION 'Insufficient seats'; END IF;
  IF t.price_per_seat > t.cost_share_cap_per_seat THEN RAISE EXCEPTION 'Trip violates cost-sharing cap'; END IF;
  IF t.ladies_only AND NOT EXISTS (
    SELECT 1 FROM public.users u WHERE u.id = v_actor_id AND u.is_female IS TRUE AND u.ekyc_tier IN ('TIER_2','TIER_3')
  ) THEN RAISE EXCEPTION 'This ride requires verified Ladies Only eligibility'; END IF;

  v_base := round(t.price_per_seat * p_quantity, 2);
  v_fee := round(v_base * p_platform_fee_bps / 10000.0, 2);

  UPDATE public.trip_routes SET available_seats = available_seats - p_quantity WHERE id = t.id;

  INSERT INTO public.escrow_orders(
    order_type,buyer_id,provider_id,trip_id,quantity,total_amount,base_price,reward_fee,platform_fee,
    currency,escrow_status,fulfillment_status,reservation_expires_at
  ) VALUES (
    'RIDE',v_actor_id,t.driver_id,t.id,p_quantity,v_base + v_fee,v_base,0,v_fee,
    t.currency,'PENDING','CREATED',now() + INTERVAL '15 minutes'
  ) RETURNING * INTO v_order;

  INSERT INTO public.escrow_events(order_id,actor_id,event_type,metadata)
  VALUES (v_order.id,v_actor_id,'ORDER_RESERVED',jsonb_build_object('quantity',p_quantity));

  PERFORM public.create_notification(
    t.driver_id,
    'RIDER_RESERVED',
    'Seat Reserved',
    'A rider has reserved ' || p_quantity || ' seat(s) on your trip',
    'ORDER',
    v_order.id,
    'ride_reserved:' || v_order.id || ':' || t.driver_id,
    v_order.id,
    t.id,
    NULL
  );

  RETURN v_order;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.reserve_ride_order(uuid, uuid, integer, integer) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.reserve_ride_order(uuid, uuid, integer, integer) TO authenticated, service_role;


-- 9. RESTORE ESTABLISHED RESERVE_SHIPMENT_ORDER RPC WITH SURGICAL GEOGRAPHIC CHECKS
CREATE OR REPLACE FUNCTION public.reserve_shipment_order(
  p_actor_id uuid,
  p_shipment_id uuid,
  p_provider_id uuid,
  p_trip_id uuid,
  p_platform_fee_bps integer,
  p_max_detour_meters integer DEFAULT 5000
)
RETURNS public.escrow_orders
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
SET row_security = off
AS $$
DECLARE
  s public.shipment_tasks;
  t public.trip_routes;
  v_actor_id uuid;
  v_pickup_frac double precision;
  v_drop_frac double precision;
  v_base numeric(12,2);
  v_fee numeric(12,2);
  v_order public.escrow_orders;
  v_req_units int;
  v_purchase public.marketplace_purchases;
BEGIN
  PERFORM set_config('row_security', 'off', true);

  IF auth.role() = 'authenticated' THEN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
    IF p_actor_id IS NOT NULL AND p_actor_id <> auth.uid() THEN RAISE EXCEPTION 'Cannot impersonate another user'; END IF;
    v_actor_id := auth.uid();
  ELSE
    v_actor_id := p_actor_id;
  END IF;

  IF v_actor_id <> p_provider_id THEN RAISE EXCEPTION 'Carrier must claim shipment personally'; END IF;
  IF p_platform_fee_bps < 0 OR p_platform_fee_bps > 3000 THEN RAISE EXCEPTION 'Invalid platform fee'; END IF;
  IF p_max_detour_meters < 1 OR p_max_detour_meters > 50000 THEN RAISE EXCEPTION 'Invalid detour limit'; END IF;

  IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = p_provider_id AND u.ekyc_tier IN ('TIER_2','TIER_3')) THEN
    RAISE EXCEPTION 'Carrier requires Tier 2 or Tier 3 eKYC';
  END IF;

  SELECT * INTO t FROM public.trip_routes WHERE id = p_trip_id FOR UPDATE;
  IF NOT FOUND OR t.driver_id <> p_provider_id OR t.status <> 'SCHEDULED' OR t.departure_time <= now() THEN RAISE EXCEPTION 'Eligible carrier route not found'; END IF;

  -- Surgical Geographic Verification for carrier route
  IF t.origin_geo IS NOT NULL THEN
    IF NOT public.is_coord_in_india(ST_Y(t.origin_geo::geometry), ST_X(t.origin_geo::geometry)) THEN
      RAISE EXCEPTION 'Carrier route origin location is outside India service coverage';
    END IF;
  END IF;
  IF t.dest_geo IS NOT NULL THEN
    IF NOT public.is_coord_in_india(ST_Y(t.dest_geo::geometry), ST_X(t.dest_geo::geometry)) THEN
      RAISE EXCEPTION 'Carrier route destination location is outside India service coverage';
    END IF;
  END IF;

  IF t.route_polyline IS NOT NULL THEN
    IF NOT public.is_route_in_india(t.route_polyline) THEN
      RAISE EXCEPTION 'Carrier route crosses outside India service coverage';
    END IF;
  END IF;

  IF t.parcel_capacity_tier = 'NONE' OR t.parcel_capacity_units_available <= 0 THEN RAISE EXCEPTION 'Route has no available parcel capacity'; END IF;

  SELECT * INTO s FROM public.shipment_tasks WHERE id = p_shipment_id FOR UPDATE;
  IF NOT FOUND OR s.status <> 'OPEN' THEN RAISE EXCEPTION 'Shipment unavailable'; END IF;

  -- Surgical Geographic Verification for shipment pickup & drop
  IF s.pickup_geo IS NOT NULL THEN
    IF NOT public.is_coord_in_india(ST_Y(s.pickup_geo::geometry), ST_X(s.pickup_geo::geometry)) THEN
      RAISE EXCEPTION 'Shipment pickup location is outside India service coverage';
    END IF;
  END IF;
  IF s.drop_geo IS NOT NULL THEN
    IF NOT public.is_coord_in_india(ST_Y(s.drop_geo::geometry), ST_X(s.drop_geo::geometry)) THEN
      RAISE EXCEPTION 'Shipment drop location is outside India service coverage';
    END IF;
  END IF;

  IF s.inspection_status <> 'APPROVED' THEN RAISE EXCEPTION 'Shipment has not passed HopShield parcel inspection'; END IF;

  v_req_units := COALESCE(s.parcel_capacity_units_required, 3);
  IF v_req_units <= 0 THEN RAISE EXCEPTION 'Invalid required parcel capacity units'; END IF;

  IF t.parcel_capacity_units_available < v_req_units THEN
    RAISE EXCEPTION 'Insufficient parcel carrying capacity on route';
  END IF;

  IF NOT public.parcel_tier_allows_weight(t.parcel_capacity_tier, s.weight_kg) THEN RAISE EXCEPTION 'Shipment exceeds route cargo tier'; END IF;
  IF NOT ST_DWithin(s.pickup_geo, t.route_polyline, p_max_detour_meters) OR NOT ST_DWithin(s.drop_geo, t.route_polyline, p_max_detour_meters) THEN
    RAISE EXCEPTION 'Shipment is outside route corridor';
  END IF;

  v_pickup_frac := ST_LineLocatePoint(t.route_polyline::geometry, s.pickup_geo::geometry);
  v_drop_frac := ST_LineLocatePoint(t.route_polyline::geometry, s.drop_geo::geometry);
  IF v_pickup_frac >= v_drop_frac THEN RAISE EXCEPTION 'Shipment direction does not match route'; END IF;

  -- =========================================================================
  -- MARKETPLACE-LINKED CROWDSHIPPING BRANCH (Payment Gate & Split Payout)
  -- =========================================================================
  IF s.marketplace_purchase_id IS NOT NULL THEN
    SELECT * INTO v_purchase FROM public.marketplace_purchases WHERE id = s.marketplace_purchase_id FOR UPDATE;
    IF NOT FOUND OR v_purchase.status = 'CANCELLED' THEN
      RAISE EXCEPTION 'Marketplace purchase for this shipment is no longer active';
    END IF;

    SELECT * INTO v_order FROM public.escrow_orders WHERE id = v_purchase.escrow_order_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Escrow order not found for marketplace purchase';
    END IF;

    -- PAYMENT SECURED GATE: Marketplace payment MUST be locked before carrier capacity is reserved
    IF v_order.escrow_status <> 'LOCKED' THEN
      RAISE EXCEPTION 'Marketplace escrow payment must be LOCKED before reserving carrier capacity';
    END IF;

    IF v_purchase.buyer_id = p_provider_id OR v_purchase.seller_id = p_provider_id THEN
      RAISE EXCEPTION 'Buyer or seller cannot carry own marketplace shipment';
    END IF;

    -- Reserve parcel capacity on carrier trip
    UPDATE public.trip_routes
    SET parcel_capacity_units_available = parcel_capacity_units_available - v_req_units, updated_at = now()
    WHERE id = t.id;

    -- Update shipment task status to MATCHED
    UPDATE public.shipment_tasks SET status = 'MATCHED'::public.shipment_status, updated_at = now() WHERE id = s.id;

    -- Link carrier trip to existing Marketplace escrow order (Zero double charge)
    UPDATE public.escrow_orders
    SET trip_id = t.id,
        reserved_parcel_capacity_units = v_req_units,
        updated_at = now()
    WHERE id = v_order.id
    RETURNING * INTO v_order;

    -- Update marketplace purchase status to HOPSTER_MATCHED
    UPDATE public.marketplace_purchases
    SET status = 'HOPSTER_MATCHED', updated_at = now()
    WHERE id = v_purchase.id;

    -- Create Hopster Delivery Reward Payout Allocation
    INSERT INTO public.escrow_payout_allocations (
      order_id, recipient_id, allocation_type, amount, currency, status, idempotency_key
    ) VALUES (
      v_order.id, p_provider_id, 'HOPSTER_REWARD', v_order.reward_fee, v_order.currency, 'PENDING',
      'hopster_reward:' || v_order.id || ':' || p_provider_id
    ) ON CONFLICT (idempotency_key) DO NOTHING;

    -- Record carrier match event
    INSERT INTO public.escrow_events(order_id, actor_id, event_type, metadata)
    VALUES (v_order.id, p_provider_id, 'ORDER_RESERVED', jsonb_build_object('trip_id', t.id, 'max_detour_meters', p_max_detour_meters, 'carrier_id', p_provider_id, 'reserved_parcel_units', v_req_units));

    -- Dispatch notification to Buyer
    PERFORM public.create_notification(
      v_purchase.buyer_id,
      'PARCEL_RESERVED',
      'Hopster matched your delivery',
      'A Hopster reserved your marketplace delivery from ' || s.pickup_name || ' to ' || s.drop_name || '.',
      'ORDER',
      v_order.id,
      'parcel_reserved_buyer:' || v_order.id || ':' || v_purchase.buyer_id,
      v_order.id,
      t.id,
      NULL
    );

    -- Dispatch notification to Seller
    PERFORM public.create_notification(
      v_purchase.seller_id,
      'PARCEL_RESERVED',
      'Hopster assigned for pickup',
      'A Hopster was assigned for pickup of your sold item from ' || s.pickup_name || '.',
      'ORDER',
      v_order.id,
      'parcel_reserved_seller:' || v_order.id || ':' || v_purchase.seller_id,
      v_order.id,
      t.id,
      NULL
    );

    RETURN v_order;
  END IF;

  -- =========================================================================
  -- NORMAL NON-MARKETPLACE SHIPMENT BRANCH
  -- =========================================================================
  IF s.sender_id = p_provider_id THEN RAISE EXCEPTION 'Sender cannot carry own shipment order'; END IF;

  UPDATE public.trip_routes
  SET parcel_capacity_units_available = parcel_capacity_units_available - v_req_units, updated_at = now()
  WHERE id = t.id;

  v_base := CASE WHEN s.item_type = 'URL_PURCHASE' THEN s.declared_value ELSE 0 END;
  v_fee := round((v_base + s.reward_amount) * p_platform_fee_bps / 10000.0, 2);

  UPDATE public.shipment_tasks SET status = 'MATCHED'::public.shipment_status, updated_at = now() WHERE id = s.id;

  INSERT INTO public.escrow_orders(
    order_type,buyer_id,provider_id,trip_id,shipment_task_id,total_amount,base_price,reward_fee,platform_fee,
    currency,escrow_status,fulfillment_status,reservation_expires_at,reserved_parcel_capacity_units
  ) VALUES (
    'SHIPMENT',s.sender_id,p_provider_id,t.id,s.id,v_base + s.reward_amount + v_fee,v_base,s.reward_amount,v_fee,
    s.currency,'PENDING','CREATED',now() + INTERVAL '30 minutes',v_req_units
  ) RETURNING * INTO v_order;

  INSERT INTO public.escrow_events(order_id,actor_id,event_type,metadata)
  VALUES (v_order.id,p_provider_id,'ORDER_RESERVED',jsonb_build_object('trip_id',t.id,'max_detour_meters',p_max_detour_meters,'payer_id',s.sender_id,'reserved_parcel_units',v_req_units));

  PERFORM public.create_notification(
    s.sender_id,
    'PARCEL_RESERVED',
    'A Hopster matched your parcel',
    'A Hopster reserved your parcel from ' || s.pickup_name || ' to ' || s.drop_name || '.',
    'ORDER',
    v_order.id,
    'parcel_reserved:' || v_order.id || ':' || s.sender_id,
    v_order.id,
    t.id,
    NULL
  );

  RETURN v_order;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.reserve_shipment_order(uuid, uuid, uuid, uuid, integer, integer) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.reserve_shipment_order(uuid, uuid, uuid, uuid, integer, integer) TO authenticated, service_role;


-- 10. ADDITIVE PERMISSIONS GUARD & TABLE ISOLATION
GRANT EXECUTE ON FUNCTION public.create_shipment_task(public.shipment_item_type, text, numeric, numeric, char, text, double precision, double precision, text, double precision, double precision, numeric) TO authenticated;

CREATE OR REPLACE FUNCTION public.has_shipment_access(p_shipment_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_sender_id uuid;
  v_has_escrow boolean;
BEGIN
  IF public.is_admin() THEN
    RETURN true;
  END IF;

  PERFORM set_config('row_security', 'off', true);

  SELECT sender_id INTO v_sender_id
  FROM public.shipment_tasks WHERE id = p_shipment_id;

  IF v_sender_id IS NOT NULL THEN
    IF v_sender_id = auth.uid() THEN
      RETURN true;
    END IF;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.escrow_orders e
    WHERE e.shipment_task_id = p_shipment_id
      AND e.escrow_status IN ('PENDING','LOCKED','RELEASED','DISPUTED')
      AND (auth.uid() = e.buyer_id OR auth.uid() = e.provider_id)
  ) INTO v_has_escrow;

  RETURN v_has_escrow;
END;
$$;

GRANT EXECUTE ON FUNCTION public.has_shipment_access(uuid) TO authenticated, service_role;

