-- 11. RE-FETCH UPDATED PURCHASE STATE IN CANCEL_MARKETPLACE_PURCHASE BEFORE RETURN
CREATE OR REPLACE FUNCTION public.cancel_marketplace_purchase(
  p_actor_id uuid,
  p_purchase_id uuid
)
RETURNS public.marketplace_purchases
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, gis, extensions
SET row_security = off
AS $$
DECLARE
  v_purchase public.marketplace_purchases;
  v_order public.escrow_orders;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_actor_id <> auth.uid() THEN
    RAISE EXCEPTION 'Cannot impersonate another user';
  END IF;

  SELECT * INTO v_purchase FROM public.marketplace_purchases WHERE id = p_purchase_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Marketplace purchase not found';
  END IF;

  IF v_purchase.buyer_id <> p_actor_id AND v_purchase.seller_id <> p_actor_id THEN
    RAISE EXCEPTION 'Unauthorized to cancel this purchase';
  END IF;

  IF v_purchase.status IN ('COMPLETED', 'IN_TRANSIT', 'AWAITING_HANDOFF') THEN
    RAISE EXCEPTION 'Completed or active in-transit sales cannot be cancelled directly. Use escrow refund lifecycle.';
  END IF;

  IF v_purchase.status = 'PAYMENT_LOCKED' THEN
    RAISE EXCEPTION 'Payment is locked in escrow. Execute canonical payment refund path to cancel.';
  END IF;

  IF v_purchase.inventory_restored THEN
    -- Idempotent cancel: return purchase without double restoration
    RETURN v_purchase;
  END IF;

  -- Update purchase status
  UPDATE public.marketplace_purchases
  SET status = 'CANCELLED', updated_at = now()
  WHERE id = v_purchase.id;

  -- Execute canonical order inventory restoration (restores stock, trip capacity, cancels payout allocations & closes shipment)
  IF v_purchase.escrow_order_id IS NOT NULL THEN
    SELECT * INTO v_order FROM public.escrow_orders WHERE id = v_purchase.escrow_order_id FOR UPDATE;
    IF FOUND AND v_order.escrow_status = 'PENDING' THEN
      PERFORM public.restore_order_inventory(v_order);
      UPDATE public.escrow_orders
      SET fulfillment_status = 'CANCELLED', reservation_expires_at = null, updated_at = now()
      WHERE id = v_order.id;

      INSERT INTO public.escrow_events(order_id, actor_id, event_type, metadata)
      VALUES (v_order.id, p_actor_id, 'ORDER_CANCELLED', jsonb_build_object('reason', 'Buyer cancelled pending marketplace reservation'));
    END IF;
  ELSE
    -- Fallback for purchase without escrow order
    PERFORM set_config('shipdehop.allow_inventory_mutation', 'true', true);
    UPDATE public.marketplace_items
    SET available_quantity = available_quantity + v_purchase.quantity,
        status = (CASE WHEN status = 'SOLD' THEN 'LISTED'::public.marketplace_item_status ELSE status END),
        updated_at = now()
    WHERE id = v_purchase.item_id;

    UPDATE public.marketplace_purchases
    SET inventory_restored = true, updated_at = now()
    WHERE id = v_purchase.id;
  END IF;

  SELECT * INTO v_purchase FROM public.marketplace_purchases WHERE id = p_purchase_id;
  RETURN v_purchase;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.cancel_marketplace_purchase(uuid, uuid) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.cancel_marketplace_purchase(uuid, uuid) TO authenticated, service_role;


-- 12. UPDATE TRIGGER TO SYNC MARKETPLACE PURCHASE STATUS TO REFUNDED ON ESCROW REFUND
CREATE OR REPLACE FUNCTION public.trg_sync_marketplace_purchase_status()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, gis, extensions
SET row_security = off
AS $$
BEGIN
  IF NEW.order_type = 'MARKETPLACE' THEN
    IF NEW.escrow_status = 'LOCKED' AND NEW.fulfillment_status = 'CREATED' THEN
      UPDATE public.marketplace_purchases
      SET status = 'PAYMENT_LOCKED', updated_at = now()
      WHERE escrow_order_id = NEW.id AND status = 'PENDING';
    ELSIF NEW.fulfillment_status IN ('VERIFIED', 'COMPLETED') OR NEW.escrow_status = 'RELEASED' THEN
      UPDATE public.marketplace_purchases
      SET status = 'COMPLETED', updated_at = now()
      WHERE escrow_order_id = NEW.id AND status <> 'COMPLETED';
    ELSIF NEW.escrow_status = 'REFUNDED' THEN
      UPDATE public.marketplace_purchases
      SET status = 'REFUNDED', updated_at = now()
      WHERE escrow_order_id = NEW.id AND status <> 'REFUNDED';
    ELSIF NEW.fulfillment_status = 'CANCELLED' THEN
      UPDATE public.marketplace_purchases
      SET status = 'CANCELLED', updated_at = now()
      WHERE escrow_order_id = NEW.id AND status <> 'CANCELLED';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


-- 13. RESTORE & GUARD LEGACY RESERVATION & ACCEPTANCE FUNCTIONS WITH SURGICAL GEOGRAPHIC CHECKS
CREATE OR REPLACE FUNCTION public.reserve_marketplace_order(
  p_actor_id uuid,
  p_item_id uuid,
  p_platform_fee_bps integer
)
RETURNS public.escrow_orders
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  i public.marketplace_items;
  v_fee numeric(12,2);
  v_order public.escrow_orders;
  v_item_lat numeric;
  v_item_lon numeric;
BEGIN
  IF auth.uid() IS NOT NULL AND auth.uid() <> p_actor_id THEN
    RAISE EXCEPTION 'Unauthorized buyer impersonation: p_actor_id must match authenticated user';
  END IF;

  IF p_platform_fee_bps < 0 OR p_platform_fee_bps > 3000 THEN RAISE EXCEPTION 'Invalid platform fee'; END IF;
  SELECT * INTO i FROM public.marketplace_items WHERE id = p_item_id FOR UPDATE;
  IF NOT FOUND OR i.status <> 'LISTED' THEN RAISE EXCEPTION 'Item unavailable'; END IF;
  IF i.seller_id = p_actor_id THEN RAISE EXCEPTION 'Seller cannot buy own item'; END IF;

  -- Surgical Geographic & Currency Verification
  IF i.location_geo IS NOT NULL THEN
    v_item_lat := ST_Y(i.location_geo::geometry);
    v_item_lon := ST_X(i.location_geo::geometry);
    IF NOT public.is_coord_in_india(v_item_lat, v_item_lon) THEN
      RAISE EXCEPTION 'Marketplace item location is outside India service coverage';
    END IF;
  END IF;

  IF UPPER(TRIM(COALESCE(i.currency, 'INR'))) <> 'INR' OR COALESCE(i.jurisdiction_code, 'IN') <> 'IN' THEN
    RAISE EXCEPTION 'Only INR transactions in India are supported for new reservations';
  END IF;

  v_fee := round(i.price * p_platform_fee_bps / 10000.0, 2);
  UPDATE public.marketplace_items SET status = 'RESERVED' WHERE id = i.id;
  INSERT INTO public.escrow_orders(
    order_type,buyer_id,provider_id,marketplace_item_id,total_amount,base_price,reward_fee,platform_fee,
    currency,escrow_status,fulfillment_status,reservation_expires_at
  ) VALUES (
    'MARKETPLACE',p_actor_id,i.seller_id,i.id,i.price + v_fee,i.price,0,v_fee,
    'INR','PENDING','CREATED',now() + INTERVAL '15 minutes'
  ) RETURNING * INTO v_order;

  INSERT INTO public.escrow_events(order_id,actor_id,event_type) VALUES (v_order.id,p_actor_id,'ORDER_RESERVED');
  RETURN v_order;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.reserve_marketplace_order(uuid, uuid, integer) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.reserve_marketplace_order(uuid, uuid, integer) TO service_role, authenticated;


CREATE OR REPLACE FUNCTION public.accept_ride_request_and_reserve_order(
  p_request_id uuid,
  p_trip_id uuid,
  p_platform_fee_bps integer DEFAULT 1000
)
RETURNS public.escrow_orders
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  req public.ride_requests;
  t public.trip_routes;
  v_base numeric(12,2);
  v_fee numeric(12,2);
  v_order public.escrow_orders;
  v_actor_id uuid := auth.uid();
BEGIN
  IF p_request_id IS NULL OR p_trip_id IS NULL THEN
    RAISE EXCEPTION 'Invalid request or trip parameters';
  END IF;

  SELECT * INTO req FROM public.ride_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Ride request not found'; END IF;
  IF req.status <> 'OPEN' THEN RAISE EXCEPTION 'Ride request is no longer open'; END IF;
  IF req.latest_departure < now() THEN RAISE EXCEPTION 'Ride request has expired'; END IF;

  SELECT * INTO t FROM public.trip_routes WHERE id = p_trip_id FOR UPDATE;
  IF NOT FOUND OR t.status NOT IN ('SCHEDULED','IN_PROGRESS') THEN RAISE EXCEPTION 'Trip unavailable'; END IF;

  IF v_actor_id IS NOT NULL AND t.driver_id <> v_actor_id AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Only the trip driver can accept a ride request for this trip';
  END IF;

  IF req.requester_id = t.driver_id THEN
    RAISE EXCEPTION 'Driver cannot accept own ride request';
  END IF;

  IF t.available_seats < req.seats_needed THEN
    RAISE EXCEPTION 'Insufficient seats available on trip';
  END IF;

  -- Surgical Geographic Verification
  IF req.pickup_geo IS NOT NULL AND NOT public.is_coord_in_india(ST_Y(req.pickup_geo::geometry), ST_X(req.pickup_geo::geometry)) THEN
    RAISE EXCEPTION 'Ride request pickup location is outside India service coverage';
  END IF;
  IF req.drop_geo IS NOT NULL AND NOT public.is_coord_in_india(ST_Y(req.drop_geo::geometry), ST_X(req.drop_geo::geometry)) THEN
    RAISE EXCEPTION 'Ride request drop location is outside India service coverage';
  END IF;
  IF t.origin_geo IS NOT NULL AND NOT public.is_coord_in_india(ST_Y(t.origin_geo::geometry), ST_X(t.origin_geo::geometry)) THEN
    RAISE EXCEPTION 'Trip origin location is outside India service coverage';
  END IF;
  IF t.dest_geo IS NOT NULL AND NOT public.is_coord_in_india(ST_Y(t.dest_geo::geometry), ST_X(t.dest_geo::geometry)) THEN
    RAISE EXCEPTION 'Trip destination location is outside India service coverage';
  END IF;
  IF t.route_polyline IS NOT NULL AND NOT public.is_route_in_india(t.route_polyline) THEN
    RAISE EXCEPTION 'Trip route crosses outside India service coverage';
  END IF;

  IF req.jurisdiction_code <> t.jurisdiction_code OR req.currency <> t.currency OR UPPER(TRIM(t.currency)) <> 'INR' THEN
    RAISE EXCEPTION 'Jurisdiction or currency mismatch or non-INR currency';
  END IF;

  IF req.earliest_departure > t.departure_time OR req.latest_departure < t.departure_time THEN
    RAISE EXCEPTION 'Ride request departure window does not overlap with trip departure time';
  END IF;

  v_base := round(t.price_per_seat * req.seats_needed, 2);
  v_fee := round(v_base * p_platform_fee_bps / 10000.0, 2);

  UPDATE public.trip_routes
  SET available_seats = available_seats - req.seats_needed
  WHERE id = t.id;

  INSERT INTO public.escrow_orders(
    order_type, buyer_id, provider_id, trip_id, quantity, total_amount, base_price, reward_fee, platform_fee,
    currency, escrow_status, fulfillment_status, reservation_expires_at
  ) VALUES (
    'RIDE', req.requester_id, t.driver_id, t.id, req.seats_needed, v_base + v_fee, v_base, 0, v_fee,
    'INR', 'PENDING', 'CREATED', now() + INTERVAL '15 minutes'
  ) RETURNING * INTO v_order;

  UPDATE public.ride_requests
  SET status = 'MATCHED',
      matched_trip_id = t.id,
      matched_order_id = v_order.id,
      updated_at = now()
  WHERE id = req.id;

  INSERT INTO public.escrow_events(order_id, actor_id, event_type, metadata)
  VALUES (v_order.id, t.driver_id, 'ORDER_RESERVED', jsonb_build_object(
    'quantity', req.seats_needed,
    'ride_request_id', req.id
  ));

  PERFORM public.create_notification(
    req.requester_id,
    'RIDE_MATCHED',
    'Your ride request was matched',
    'Driver matched your ride from ' || req.pickup_name || ' to ' || req.drop_name || '.',
    'ORDER',
    v_order.id,
    'ride_match:' || req.id || ':' || req.requester_id,
    v_order.id,
    t.id,
    req.id
  );

  RETURN v_order;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.accept_ride_request_and_reserve_order(uuid, uuid, integer) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.accept_ride_request_and_reserve_order(uuid, uuid, integer) TO service_role, authenticated;

